import { httpGet } from '../../mochiws/index.js';
import { URL } from '../../mochiurl/index.js';
import { TextDecoder, TextEncoder } from '../../mochiglobals/script/index.js';

function normalizeName(name) {
    return String(name).toLowerCase();
}

function normalizeValue(value) {
    return String(value);
}

export class Headers {
    constructor(init) {
        this._map = {};
        if (init instanceof Headers) {
            init.forEach((value, name) => this.append(name, value));
        } else if (Array.isArray(init)) {
            for (const pair of init) {
                if (Array.isArray(pair) && pair.length >= 2) this.append(pair[0], pair[1]);
            }
        } else if (init && typeof init === 'object') {
            for (const name of Object.keys(init)) this.append(name, init[name]);
        }
    }

    append(name, value) {
        const key = normalizeName(name);
        const val = normalizeValue(value);
        const old = this._map[key];
        this._map[key] = old === undefined ? val : old + ', ' + val;
    }

    set(name, value) {
        this._map[normalizeName(name)] = normalizeValue(value);
    }

    get(name) {
        const value = this._map[normalizeName(name)];
        return value === undefined ? null : value;
    }

    has(name) {
        return this._map[normalizeName(name)] !== undefined;
    }

    delete(name) {
        delete this._map[normalizeName(name)];
    }

    forEach(callback, thisArg) {
        for (const name of Object.keys(this._map)) {
            callback.call(thisArg || undefined, this._map[name], name, this);
        }
    }

    entries() {
        return Object.keys(this._map).map((name) => [name, this._map[name]]);
    }

    keys() {
        return Object.keys(this._map);
    }

    values() {
        return Object.keys(this._map).map((name) => this._map[name]);
    }
}

function copyBytes(bytes) {
    const out = new Uint8Array(bytes.length);
    for (let i = 0; i < bytes.length; i++) out[i] = bytes[i];
    return out;
}

function hexToBytes(hex) {
    const s = String(hex || '').replace(/[^0-9a-fA-F]/g, '');
    const out = new Uint8Array(Math.floor(s.length / 2));
    for (let i = 0; i < out.length; i++) {
        out[i] = parseInt(s.slice(i * 2, i * 2 + 2), 16) || 0;
    }
    return out;
}

export class Request {
    constructor(input, init = {}) {
        const src = input instanceof Request ? input.url : String(input == null ? '' : input);
        this.url = new URL(src).toString();
        this.method = String(init.method || (input instanceof Request ? input.method : 'GET')).toUpperCase();
        this.headers = new Headers(init.headers || (input instanceof Request ? input.headers : undefined));
        this.signal = init.signal || null;
        this.bodyUsed = false;
        this.duplex = 'half';
    }

    async arrayBuffer() {
        this.bodyUsed = true;
        return new Uint8Array(0).buffer;
    }

    async text() {
        this.bodyUsed = true;
        return '';
    }
}

export class Response {
    constructor(body = null, init = {}) {
        this.status = Number(init.status || 200);
        this.statusText = String(init.statusText || (this.status === 200 ? 'OK' : ''));
        this.headers = new Headers(init.headers);
        this.ok = this.status >= 200 && this.status < 300;
        this.url = String(init.url || '');
        this.redirected = false;
        this.type = 'basic';
        this.bodyUsed = false;
        if (body === null || body === undefined) {
            this._body = new Uint8Array(0);
        } else if (body instanceof Uint8Array) {
            this._body = body;
        } else if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(body)) {
            this._body = new Uint8Array(body.buffer, body.byteOffset, body.byteLength);
        } else if (typeof ArrayBuffer !== 'undefined' && body instanceof ArrayBuffer) {
            this._body = new Uint8Array(body);
        } else {
            this._body = new TextDecoder().decode(new Uint8Array(0));
            this._body = new TextEncoder().encode(String(body));
        }
    }

    get body() {
        const bytes = this._body;
        return {
            async *[Symbol.asyncIterator]() {
                yield bytes;
            }
        };
    }

    async arrayBuffer() {
        if (this.bodyUsed) throw new TypeError('body already used');
        this.bodyUsed = true;
        return copyBytes(this._body).buffer;
    }

    async text() {
        if (this.bodyUsed) throw new TypeError('body already used');
        this.bodyUsed = true;
        return new TextDecoder().decode(this._body);
    }

    async json() {
        return JSON.parse(await this.text());
    }

    clone() {
        return new Response(copyBytes(this._body), {
            status: this.status,
            statusText: this.statusText,
            headers: this.headers,
            url: this.url
        });
    }

    static redirect(url, status = 302) {
        return new Response(null, { status, headers: { location: String(url) } });
    }
}

export function fetch(input, init = {}) {
    try {
        const req = new Request(input, init);
        if (req.method !== 'GET' && req.method !== 'HEAD') {
            throw new Error('mochifetch: ' + req.method + ' is unavailable on MochiBerry runtime');
        }
        if (req.signal && req.signal.aborted) {
            return Promise.reject(req.signal.reason);
        }
        return Promise.resolve().then(() => {
            const result = httpGet(req.url);
            return new Response(hexToBytes(result.bodyHex), {
                status: result.status,
                headers: result.headers,
                url: req.url
            });
        });
    } catch (error) {
        return Promise.reject(error);
    }
}

export function install(target = globalThis) {
    if (typeof target.fetch === 'undefined') target.fetch = fetch;
    if (typeof target.Headers === 'undefined') target.Headers = Headers;
    if (typeof target.Request === 'undefined') target.Request = Request;
    if (typeof target.Response === 'undefined') target.Response = Response;
    return target;
}

install();

export default { fetch, Headers, Request, Response, install };
